{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Verapamil absolute oral bioavailability in humans was 34%, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Noscapine absolute oral bioavailability in healthy volunteers was 30%, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Sulpiride absolute oral bioavailability in humans was 35%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide absolute oral bioavailability in normal subjects was 32 ± 7%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Praziquantel oral bioavailability was 27.2 ± 5.4% in patients, above the 20% threshold, although measured in a diseased population.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "One verapamil study in 20 normal young men reported absolute bioavailability of 19.4%, slightly below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Direct human bioavailability measurements for five related moderate-bioavailability drugs cluster at 22-42%, with most values at or above 20%; the few sub-20 values are borderline and outweighed. The mixed physicochemical prior does not override this consistent experimental evidence, so F >= 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement for the query molecule itself.",
    "Structural similarity between the query and the cited evidence molecules is not visible in this ablation, limiting transferability.",
    "Some records are from diseased populations (e.g., cirrhosis, hepatic disease) and may not reflect normal oral bioavailability.",
    "Several records are qualitative or unspecified in bioavailability type; only absolute measurements are directly threshold-relevant."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

